<?php require 'config.php';if($_SERVER['REQUEST_METHOD']==='POST'){verify();$id=(int)($_POST['id']??0);$s=$db->prepare('SELECT id FROM products WHERE id=? AND active=1');$s->execute([$id]);if($s->fetch())$_SESSION['cart'][$id]=min(20,($_SESSION['cart'][$id]??0)+1);go('cart.php');}head('Menu');?><section class="hero"><h1>Fresh food, easy ordering 🍕</h1><p>Choose your favorite meal and place a demo order.</p></section><h2>Food Menu</h2><div class="grid"><?php foreach($db->query('SELECT * FROM products WHERE active=1 ORDER BY category,name') as $p):?><article class="card"><div class="emoji">🍽️</div><small><?=h($p['category'])?></small><h3><?=h($p['name'])?></h3><p>ETB <?=h($p['price'])?></p><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="id" value="<?=h($p['id'])?>"><button>Add to cart +</button></form></article><?php endforeach;?></div><?php foot();?>
